const ThemeCtx=createContext<V3Preferences|null>(null);
type FrameEditorTarget={page:PageFieldKey;cardId:string};
type EditorRuntime={nodes:Record<string,UniversalEditorNode>;globalEditMode:boolean;open:(node:UniversalEditorNode)=>void;openFrame:(target:FrameEditorTarget)=>void};
const EditorCtx=createContext<EditorRuntime|null>(null);
const defaultNode=(id:string,kind:EditableUiKind,name:string,style?:Partial<ReturnType<typeof defaultTextStyle>>):UniversalEditorNode=>({id,kind,systemName:name,text:{...defaultTextStyle(),...style},backgroundColorMode:'theme',borderColorMode:'theme',effects:[]});
function normalizeEditorNodeForRender(base:UniversalEditorNode,saved?:UniversalEditorNode):UniversalEditorNode{const text={...defaultTextStyle(),...(base.text??{}),...(saved?.text??{})};return withUniversalDefaults({...base,...(saved??{}),text,effects:Array.isArray(saved?.effects)?saved.effects:base.effects} as UniversalEditorNode);}
export function V3ThemeProvider({prefs,editorPreviewValues,onEditorNodesChange,onPreferencesChange,children}:{prefs:V3Preferences;editorPreviewValues?:Partial<Record<PageFieldKey,Record<string,string>>>;onEditorNodesChange?:(nodes:Record<string,UniversalEditorNode>)=>void;onPreferencesChange?:(patch:Partial<V3Preferences>)=>void;children:React.ReactNode}){const[editing,setEditing]=useState<UniversalEditorNode|null>(null);const[clipboard,setClipboard]=useState<UniversalEditorNode|null>(null);const[frameTarget,setFrameTarget]=useState<FrameEditorTarget|null>(null);const save=(node:UniversalEditorNode)=>{onEditorNodesChange?.({...prefs.editorNodes,[node.id]:node});setEditing(null)};const apply=(scope:'page'|'app')=>{if(!editing)return;const prefix=editing.id.split(':').slice(0,2).join(':');const next={...prefs.editorNodes};for(const [id,node] of Object.entries(next))if(node.kind===editing.kind&&(scope==='app'||id.startsWith(prefix)))next[id]={...editing,id,systemName:node.systemName,displayName:node.displayName};onEditorNodesChange?.(next)};return <ThemeCtx.Provider value={prefs}><EditorCtx.Provider value={{nodes:prefs.editorNodes??{},globalEditMode:prefs.globalEditMode,open:setEditing,openFrame:setFrameTarget}}>{children}{editing?<UniversalEditor visible node={editing} onClose={()=>setEditing(null)} onSave={save} onReset={()=>save(defaultNode(editing.id,editing.kind,editing.systemName))} onCopyStyle={()=>{if(clipboard){setEditing({...editing,text:clipboard.text?{...clipboard.text}:editing.text,backgroundColorMode:clipboard.backgroundColorMode,backgroundColor:clipboard.backgroundColor,borderColorMode:clipboard.borderColorMode,borderColor:clipboard.borderColor,effects:clipboard.effects.map(x=>({...x,id:`${x.kind}-${Date.now()}-${x.order}`}))});Alert.alert('樣式已貼上','已將先前複製的樣式貼到目前物件，按「套用 / 儲存」後生效。')}else{setClipboard(editing);Alert.alert('樣式已複製','開啟另一個同類型物件後，再按一次「複製 / 貼上樣式」。')}}} onApplyScope={apply}/>:null}<GlobalCardDesigner visible={!!frameTarget} layouts={prefs.pageLayouts} previewValuesByPage={editorPreviewValues} choicesByPage={Object.fromEntries((Object.keys(pageLabels) as PageFieldKey[]).map(k=>[k,pageFieldChoices[k].filter(([key])=>fieldAllowed(prefs,key)).map(([key,label])=>({key,label}))])) as any} entryTarget={frameTarget??undefined} directMode presets={prefs.editorPresets} editorNodes={prefs.editorNodes??{}} onEditorNodesChange={onEditorNodesChange} onPresetsChange={editorPresets=>onPreferencesChange?.({editorPresets})} onSave={pageLayouts=>onPreferencesChange?.({pageLayouts})} onClose={()=>setFrameTarget(null)}/></EditorCtx.Provider></ThemeCtx.Provider>}
function theme(){return useContext(ThemeCtx)}
function useEditorNode(id:string,kind:EditableUiKind,systemName:string,style?:any){const editor=useContext(EditorCtx);const flat=StyleSheet.flatten(style)||{};const base=defaultNode(id,kind,systemName,{fontSize:Number(flat.fontSize)||14,fontWeight:flat.fontWeight||'700'});return {editor,node:normalizeEditorNodeForRender(base,editor?.nodes[id])}}
function useEffectAnimation(node:UniversalEditorNode){const progress=useRef(new Animated.Value(0)).current;const active=node.effects.filter(x=>x.enabled);const animated=active.find(x=>['breathe','blink','alertPulse','scalePulse','fadeInOut','shimmer','sweep'].includes(x.kind));useEffect(()=>{progress.stopAnimation();progress.setValue(0);if(!animated)return;const loop=Animated.loop(Animated.sequence([Animated.timing(progress,{toValue:1,duration:Math.max(125,animated.speedMs/2),useNativeDriver:true}),Animated.timing(progress,{toValue:0,duration:Math.max(125,animated.speedMs/2),useNativeDriver:true})]));loop.start();return()=>loop.stop()},[animated?.id,animated?.enabled,animated?.speedMs,progress]);if(!animated)return {};const amount=Math.max(.02,animated.intensity/500);return {opacity:progress.interpolate({inputRange:[0,1],outputRange:[Math.max(.15,1-amount*2),1]}),transform:[{scale:progress.interpolate({inputRange:[0,1],outputRange:[1,animated.kind==='scalePulse'||animated.kind==='alertPulse'?1+amount:1]})}]}}
function EditableText({id,kind,systemName,pnl,style,children}:{id:string;kind:EditableUiKind;systemName:string;pnl?:number;style?:any;children?:React.ReactNode}){const p=theme();const {editor,node}=useEditorNode(id,kind,systemName,style);const animatedStyle=useEffectAnimation(node);const palette={positive:p?.positiveColor??'#E54A45',negative:p?.negativeColor??'#12A875',neutral:p?.secondaryTextColor??'#8E9BAE'};const color=resolveColor(node.text!.colorMode,node.text!.color,StyleSheet.flatten(style)?.color??p?.primaryTextColor??'#fff',pnl,palette);if(!node.text!.visible)return null;return <Animated.Text onLongPress={p?.globalEditMode?()=>editor?.open(node):undefined} accessibilityHint={p?.globalEditMode?"長按開啟統一編輯器":undefined} style={[style,textStyleFor(node.text!,color),effectsStyle(node.effects,color),animatedStyle]}>{node.displayName!=null?displayNameOf(node):children??systemName}</Animated.Text>}

export function ScreenTitle({title,subtitle,onSettings,onPrivacy,privacy,onAi,customizeEnabled,onToggleCustomize}:{title:string;subtitle:string;onSettings?:()=>void;onPrivacy?:()=>void;privacy?:boolean;onAi?:()=>void;customizeEnabled?:boolean;onToggleCustomize?:()=>void}){const p=theme();const key=title.replace(/\s/g,'-');const pulse=useRef(new Animated.Value(.72)).current;useEffect(()=>{if(!onAi)return;const loop=Animated.loop(Animated.sequence([Animated.timing(pulse,{toValue:1,duration:900,useNativeDriver:true}),Animated.timing(pulse,{toValue:.72,duration:900,useNativeDriver:true})]));loop.start();return()=>loop.stop()},[onAi,pulse]);return <View style={s.titleRow}><View style={{flex:1}}><EditableText id={`page:${key}:status`} kind="statusBar" systemName={`ETF 財務管家 ${APP_DISPLAY_VERSION}`} style={[s.eyebrow,{color:p?.accentColor??'#d4af37'}]}/><EditableText id={`page:${key}:title`} kind="title" systemName={title} style={[s.title,{color:p?.primaryTextColor??'#fff'}]}/><EditableText id={`page:${key}:subtitle`} kind="subtitle" systemName={subtitle} style={[s.subtitle,{color:p?.secondaryTextColor??'#8E9BAE'}]}/></View><View style={s.titleActions}>{onAi&&p?.ai?.enabled!==false&&p?.ai?.showHeaderButton!==false?<Animated.View style={{opacity:pulse,transform:[{scale:pulse.interpolate({inputRange:[.72,1],outputRange:[.94,1.06]})}]}}><TouchableOpacity style={[s.roundBtn,{borderColor:'rgba(76,201,240,.55)'}]} onPress={onAi}><Text style={[s.roundBtnText,{color:'#7DD3FC'}]}>✦</Text></TouchableOpacity></Animated.View>:null}{onToggleCustomize?<TouchableOpacity accessibilityLabel="頁面自訂模式" style={[s.pageCustomizeButton,customizeEnabled&&{borderColor:p?.accentColor??'#d4af37',backgroundColor:'rgba(212,175,55,.13)'}]} onPress={onToggleCustomize}><Text style={[s.pageCustomizeIcon,customizeEnabled&&{color:p?.accentColor??'#f3d675'}]}>{customizeEnabled?'🔓':'🔒'}</Text><Text style={[s.pageCustomizeText,customizeEnabled&&{color:p?.accentColor??'#f3d675'}]}>自訂模式</Text></TouchableOpacity>:null}{onPrivacy?<TouchableOpacity style={s.roundBtn} onPress={onPrivacy}><Text style={s.roundBtnText}>{privacy?'◉':'◎'}</Text></TouchableOpacity>:null}{onSettings?<TouchableOpacity style={s.roundBtn} onPress={onSettings}><Text style={s.roundBtnText}>⚙</Text></TouchableOpacity>:null}</View></View>}
function Card({children,style,editTarget}:{children:React.ReactNode;style?:any;editTarget?:FrameEditorTarget}){const p=theme();const editor=useContext(EditorCtx);const registered=editTarget?p?.pageLayouts?.[editTarget.page]?.cards?.find(c=>c.id===editTarget.cardId):undefined;if(registered?.hidden)return null;const wrap=(body:React.ReactNode)=>editTarget&&p?.globalEditMode?<Pressable onLongPress={()=>editor?.openFrame(editTarget)} delayLongPress={360}>{body}</Pressable>:body;const registeredStyle=registered?{borderRadius:registered.style.radius,backgroundColor:'#FFFFFF',borderColor:'#E2E8F0',padding:registered.style.padding}:undefined;const base=[s.card,p&&{borderRadius:p.cardRadius,backgroundColor:'#FFFFFF',borderColor:'#E2E8F0'},registeredStyle,p?.globalEditMode&&editTarget?{borderWidth:1.5,borderColor:'#0066FF'}:undefined,style];if(p?.cardBackgroundImageUri)return wrap(<View style={[base,{padding:0}]}><ImageBackground source={{uri:p.cardBackgroundImageUri}} resizeMode="cover" style={[s.cardImage,{padding:14,borderRadius:p.cardRadius}]} imageStyle={{borderRadius:p.cardRadius,opacity:Math.max(0,Math.min(1,p.cardBackgroundImageOpacity/100))}}>{children}</ImageBackground></View>);return wrap(<View style={base}>{children}</View>)}
function SectionTitle({title,right}:{title:string;right?:string}){const p=theme();const id=title.replace(/\s/g,'-');return <View style={s.sectionTitle}><EditableText id={`section:${id}:title`} kind="section" systemName={title} style={[s.sectionTitleText,{color:p?.primaryTextColor??'#fff'}]}/>{right?<EditableText id={`section:${id}:status`} kind="label" systemName={right} style={[s.sectionRight,{color:p?.accentColor??'#d4af37'}]}/>:null}</View>}
function MoneyText({children,positive,privacy,big}:{children:React.ReactNode;positive?:boolean;privacy?:boolean;big?:boolean}){const p=theme();return <Text style={[s.money,{color:p?.primaryTextColor??'#fff'},big&&[s.moneyBig,{color:p?.accentColor??'#f3d675'}],positive!==undefined&&{color:positive?(p?.positiveColor??'#30d158'):(p?.negativeColor??'#ff6b61')}]}>{privacy?'••••••':children}</Text>}

function homeMetricValue(k:HomeMetricKey,m:any){const v=m[k];if(k==='totalRoi'||k==='todayPnlPct')return pct(Number(v||0));if(k==='holdingCount')return `${v??0} 檔`;const n=Number(v||0);return `${n<0?'-':''}${money(Math.abs(n))}`;}

const portfolioListTemplate=(prefs:V3Preferences)=>prefs.pageLayouts?.portfolio?.cards?.find(c=>c.role==='listTemplate'||c.id==='portfolio-list');
const chartTypeLabel=(t:V3ChartConfig['chartType'])=>({line:'折線圖',area:'面積圖',bar:'柱狀圖',positiveBar:'正負柱狀圖',multiLine:'多折線圖',pie:'圓餅圖',donut:'環形圖',stackedBar:'堆疊柱狀圖',candlestick:'K 線圖',volume:'成交量圖',pnlTrend:'損益走勢圖',progress:'目標進度圖',heatmap:'熱力圖',waterfall:'瀑布圖',radar:'雷達圖',scatter:'散佈圖'} as Record<string,string>)[t??'line']??'折線圖';

function sortFocusHoldings(rows:Holding[],prefs:V3Preferences,quotes:Record<string,QuoteLike>,ledger:LedgerEntry[],dividends:DividendEvent[]){if(prefs.holdingFocusSort==='custom')return rows;return [...rows].sort((a,b)=>{const aa=calculateHoldingView(a,quotes,ledger,dividends),bb=calculateHoldingView(b,quotes,ledger,dividends);return Number((bb as any)[prefs.holdingFocusSort]??0)-Number((aa as any)[prefs.holdingFocusSort]??0)});}
function WatchDragHandle({onMove}:{onMove:(by:number)=>void}){const pan=useMemo(()=>PanResponder.create({onStartShouldSetPanResponder:()=>true,onMoveShouldSetPanResponder:(_,g)=>Math.abs(g.dy)>4,onPanResponderRelease:(_,g)=>{const by=Math.round(g.dy/52);if(by)onMove(by)}}),[onMove]);return <View accessibilityLabel="拖曳排序自選 ETF" {...pan.panHandlers} style={s.watchDrag}><Text style={s.watchButtonText}>☰</Text></View>}

function MarketOverviewPanel({common}:{common:ScreenCommon}){
 const {catalog,loading,error}=useEtfCatalog();
 const live=useTwseQuotes(featuredEtfSymbols,common.prefs.market,{refreshOnForeground:true});
 const [query,setQuery]=useState('');
 const [category,setCategory]=useState<EtfCategory>('all');
 const [marketFilter,setMarketFilter]=useState<'all'|'watchlist'|'held'|'popular'>('all');
 const [marketExpanded,setMarketExpanded]=useState(false);
 const categories:Array<[EtfCategory,string]>=[['all','全部'],['market','市值型'],['dividend','高股息'],['tech','科技'],['bond','債券'],['leveraged','槓反'],['active','主動'],['esg','ESG']];
 const results=useMemo(()=>{
  const base=query.trim()?searchEtfCatalog(catalog,query,40):catalog;
  const held=new Set(common.holdings.map(h=>h.symbol));const watch=new Set(common.prefs.watchlistSymbols??[]);const popular=new Set(featuredEtfSymbols);
  const filtered=base.filter(x=>(category==='all'||classifyEtf(x.symbol,x.name).includes(category))&&(marketFilter==='all'||marketFilter==='watchlist'&&watch.has(x.symbol)||marketFilter==='held'&&held.has(x.symbol)||marketFilter==='popular'&&popular.has(x.symbol)));if(marketFilter==='watchlist'){const rank=new Map((common.prefs.watchlistSymbols??[]).map((x,i)=>[x,i]));filtered.sort((a,b)=>(rank.get(a.symbol)??999)-(rank.get(b.symbol)??999))}return filtered.slice(0,40);
 },[catalog,query,category,marketFilter,common.holdings,common.prefs.watchlistSymbols]);
 const ranked=useMemo(()=>featuredEtfSymbols.map(symbol=>{const meta=catalog.find(x=>x.symbol===symbol);const q=(live.quotes as any)[symbol]??common.quotes[symbol]??{};return {symbol,name:meta?.name??symbol,price:Number(q.price),changePercent:Number(q.changePercent),volume:Number(q.volume)}}).filter(x=>Number.isFinite(x.price)&&x.price>0).sort((a,b)=>(Number.isFinite(b.changePercent)?b.changePercent:-999)-(Number.isFinite(a.changePercent)?a.changePercent:-999)),[catalog,live.quotes,common.quotes]);
 const visibleRanked=marketExpanded?ranked.slice(0,5):ranked.slice(0,3);
 const visibleResults=query.trim()?results:(marketExpanded?results:results.slice(0,5));
 const selected=common.prefs.watchlistSymbols??[];
 const toggle=(symbol:string)=>{const next=selected.includes(symbol)?selected.filter(x=>x!==symbol):[...selected,symbol];common.onSetWatchlistSymbols?.(next)};
 const move=(symbol:string,by:number)=>{const from=selected.indexOf(symbol),to=Math.max(0,Math.min(selected.length-1,from+by));if(from<0||from===to)return;const next=[...selected];next.splice(to,0,next.splice(from,1)[0]);common.onSetWatchlistSymbols?.(next)};
 return <>
  <Card editTarget={{page:'dashboard',cardId:'dashboard-market'}}><SectionTitle title="市場總覽｜熱門 ETF" right={`${live.source??'TWSE'} · ${live.controllerStatus}`}/>{ranked.length?<>{visibleRanked.map((x,i)=><View key={x.symbol} style={s.marketRankRow}><Text style={s.rankNum}>{i+1}</Text><SymbolBadge symbol={x.symbol}/><View style={{flex:1}}><Text style={s.etfName}>{x.name}</Text><Text style={s.muted}>成交量 {Number.isFinite(x.volume)?Math.round(x.volume).toLocaleString():'—'}</Text></View><View style={{alignItems:'flex-end'}}><Text style={s.marketPrice}>{x.price.toFixed(2)}</Text><Text style={[s.etfPnl,{color:(x.changePercent||0)>=0?common.prefs.positiveColor:common.prefs.negativeColor}]}>{Number.isFinite(x.changePercent)?pct(x.changePercent):'—'}</Text></View></View>)}</>:<Text style={s.empty}>{live.error||'目前無熱門 ETF 即時行情；可手動更新市場資料後再看排行。'}</Text>}</Card>
  <Card editTarget={{page:'dashboard',cardId:'dashboard-watchlist'}}><SectionTitle title="ETF 搜尋 / 自選管理" right={loading?'同步 TWSE 主檔中':`${catalog.length} 檔`}/><View style={s.wrapRow}>{([['all','全部'],['watchlist','★ 自選'],['held','持有'],['popular','熱門']] as const).map(([k,label])=><Choice key={k} active={marketFilter===k} label={label} onPress={()=>setMarketFilter(k)}/>)}</View><TextInput value={query} onChangeText={setQuery} placeholder="輸入 ETF 代號或名稱" placeholderTextColor="rgba(255,255,255,.35)" style={s.searchInput} autoCapitalize="characters"/><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.filterChips}>{categories.map(([k,label])=><Choice key={k} active={category===k} label={label} onPress={()=>setCategory(k)}/>)}</ScrollView>{error?<Text style={s.note}>TWSE 主檔暫時不可用，已使用離線 ETF 基本清單。</Text>:null}<Text style={s.note}>自選只保存顯示順序，不會建立持倉，也不會修改成本、資產、損益或股息帳務。切換到 ★ 自選後可拖曳 ☰ 排序。</Text><View style={s.candidateBox}>{visibleResults.length?visibleResults.map(x=>{const watch=selected.includes(x.symbol);const q=(live.quotes as any)[x.symbol]??common.quotes[x.symbol];return <View key={x.symbol} style={s.candidateRow}>{marketFilter==='watchlist'?<WatchDragHandle onMove={by=>move(x.symbol,by)}/>:null}<SymbolBadge symbol={x.symbol}/><View style={{flex:1}}><Text style={s.etfName}>{x.name}</Text><Text style={s.muted}>{q?.price?`${Number(q.price).toFixed(2)} · ${Number.isFinite(Number(q.changePercent))?pct(Number(q.changePercent)):'行情更新中'}`:x.source==='TWSE'?'TWSE 主檔':'離線主檔'}</Text></View><TouchableOpacity style={[s.watchButton,watch&&s.watchButtonActive]} onPress={()=>toggle(x.symbol)}><Text style={[s.watchButtonText,watch&&{color:common.prefs.accentColor}]}>{watch?'★':'☆'}</Text></TouchableOpacity></View>}):<Text style={s.empty}>沒有符合條件的 ETF。</Text>}</View>{!query.trim()&&results.length>5?<TouchableOpacity style={s.secondary} onPress={()=>setMarketExpanded(v=>!v)}><Text style={s.secondaryText}>{marketExpanded?'收合市場列表':'展開市場列表'} · {results.length} 檔</Text></TouchableOpacity>:null}</Card>
 </>;
}

function EtfRiskResearch({symbol,prefs}:{symbol:string;prefs:V3Preferences}){
 const [history,setHistory]=useState<any[]>([]); const [loading,setLoading]=useState(true); const [error,setError]=useState('');
 useEffect(()=>{let active=true;setLoading(true);setError('');fetchTwseOhlcvHistory(symbol,260).then(rows=>{if(active)setHistory(rows)}).catch(e=>{if(active)setError(e instanceof Error?e.message:'歷史行情讀取失敗')}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[symbol]);
 const r=useMemo(()=>calculateEtfRiskStats(history),[history]);
 const fp=(v?:number,d=2)=>v==null||!Number.isFinite(v)?'資料不足':`${v>=0?'+':''}${v.toFixed(d)}%`;
 const fn=(v?:number,d=2)=>v==null||!Number.isFinite(v)?'資料不足':v.toFixed(d);
 return <Card><SectionTitle title="風險指標｜TWSE 歷史行情" right={loading?'讀取中':`${r.observations} 日`}/>{error?<Text style={s.empty}>{error}</Text>:<View style={s.metricGrid}><Metric label="1 週報酬" value={fp(r.return1w)}/><Metric label="1 月報酬" value={fp(r.return1m)}/><Metric label="3 月報酬" value={fp(r.return3m)}/><Metric label="1 年報酬" value={fp(r.return1y)}/><Metric label="年化波動率" value={r.volatility==null?'資料不足':`${r.volatility.toFixed(2)}%`}/><Metric label="最大回撤" value={r.maxDrawdown==null?'資料不足':`${r.maxDrawdown.toFixed(2)}%`}/><Metric label="Sharpe（RF=0）" value={fn(r.sharpe)}/><Metric label="Beta" value="待基準指數資料"/></View>}<Text style={s.note}>風險值由 TWSE 歷史收盤價計算；Beta 必須有可靠追蹤指數/基準序列，因此目前不以 0050 或其他 ETF 假裝基準。</Text></Card>;
}

