 const normalizeCurrentByMarket=(symbols:string[])=>{const rows=holdingRows.filter(x=>symbols.includes(x.h.symbol)),total=rows.reduce((a,x)=>a+x.hm.marketValue,0);return Object.fromEntries(rows.map(x=>[x.h.symbol,total?x.hm.marketValue/total*100:100/Math.max(1,rows.length)]))};
