function CumulativePnlModal({visible,onClose,metrics,snapshots,prefs}:{visible:boolean;onClose:()=>void;metrics:any;snapshots:DailySnapshot[];prefs:V3Preferences}){const rows=[...snapshots].sort((a,b)=>b.date.localeCompare(a.date));return <Modal visible={visible} transparent animationType="slide" onRequestClose={onClose}><View style={s.modalBackdrop}><View style={[s.sheet,{maxHeight:'88%'}]}><View style={s.sheetHandle}/><SectionTitle title="累積損益 TOTAL" right={`${rows.length} 日紀錄`}/><ScrollView><View style={s.metricGrid}><Metric label="即時未實現（含費）" value={`${metrics.cashUnrealizedPnl>=0?'+':''}${money(metrics.cashUnrealizedPnl)}`} positive={metrics.cashUnrealizedPnl>=0}/><Metric label="已實現（含費）" value={`${metrics.realizedCashPnl>=0?'+':''}${money(metrics.realizedCashPnl)}`} positive={metrics.realizedCashPnl>=0}/><Metric label="累積配息" value={`+${money(metrics.cumulativeDividends)}`} positive/><Metric label="TOTAL" value={`${metrics.totalPnl>=0?'+':''}${money(metrics.totalPnl)}`} positive={metrics.totalPnl>=0}/><Metric label="總報酬率" value={pct(metrics.totalRoi)} positive={metrics.totalRoi>=0}/><Metric label="目前含費成本" value={`${money(metrics.currentCashBasis)}`}/></View><Text style={s.note}>TOTAL = 即時未實現損益（含目前持有買進手續費）＋已實現含費損益＋累積配息；各項不重複加總。</Text><Card><SectionTitle title="歷史總結紀錄" right="最新在前"/>{rows.length?rows.slice(0,120).map(r=><View key={r.id||r.date} style={s.historyRow}><Text style={s.historyKind}>{r.date.slice(5)}</Text><View style={{flex:1}}><Text style={s.etfName}>總損益 {Number(r.totalPnl)>=0?'+':''}${money(Number(r.totalPnl||0))}</Text><Text style={s.muted}>今日 {Number(r.todayPnl)>=0?'+':''}${money(Number(r.todayPnl||0))} · 資產 ${money(Number(r.totalAssets??r.marketValue??0))}</Text></View></View>):<Text style={s.empty}>尚無每日損益快照。</Text>}</Card></ScrollView><TouchableOpacity style={s.secondary} onPress={onClose}><Text style={s.secondaryText}>關閉</Text></TouchableOpacity></View></View></Modal>}
