function SelectedMetrics({page,common,prefs,fields,choices,values,spans={},dailySnapshots=[],intradayPnlPoints=[]}:{page:PageFieldKey;common?:ScreenCommon;prefs:V3Preferences;fields:string[];choices:Array<[string,string]>;values:Record<string,string>;spans?:Record<string,V3CardSpan>;dailySnapshots?:DailySnapshot[];intradayPnlPoints?:IntradayPnlPoint[]}){const visible=fields.filter(k=>fieldAllowed(prefs,k));const layout=prefs.pageLayouts?.[page];const hasDesignedCards=!!layout?.cards?.some(c=>!c.hidden&&c.role!=='listTemplate');if(hasDesignedCards)return <PageCardDeck page={page} common={common} prefs={prefs} choices={choices} values={values} dailySnapshots={dailySnapshots} intradayPnlPoints={intradayPnlPoints}/>;return <FieldMetricGrid fields={visible} choices={choices} values={values} spans={spans} prefs={prefs}/>;}
