function FieldPicker({choices,selected,onToggle}:{choices:Array<[string,string]>;selected:string[];onToggle:(key:string)=>void}){return <View style={s.wrapRow}>{choices.map(([k,l])=><Choice key={k} active={selected.includes(k)} label={l} onPress={()=>onToggle(k)}/>)}</View>}
