function DecimalSettingField({label,value,onCommit,min=0,max=1,digits=6,hint}:{label:string;value:number;onCommit:(n:number)=>void;min?:number;max?:number;digits?:number;hint?:string}){const p=theme();const format=(n:number)=>Number.isFinite(n)?String(Number(n.toFixed(digits))):'';const [draft,setDraft]=useState(()=>format(value));useEffect(()=>setDraft(format(value)),[value]);const commit=()=>{const normalized=draft.trim().startsWith('.')?`0${draft.trim()}`:draft.trim();const parsed=Number(normalized);if(!Number.isFinite(parsed)){setDraft(format(value));return}const safe=Math.max(min,Math.min(max,parsed));setDraft(format(safe));onCommit(safe)};return <View style={s.field}><Text style={[s.fieldLabel,{color:p?.secondaryTextColor??'rgba(255,255,255,.56)'}]}>{label}</Text><View style={s.inputWrap}><TextInput style={[s.input,{color:p?.primaryTextColor??'#fff'}]} value={draft} onChangeText={v=>{if(/^\d*(?:\.\d*)?$/.test(v))setDraft(v)}} onBlur={commit} onEndEditing={commit} keyboardType="decimal-pad" inputMode="decimal" placeholder="0.65" placeholderTextColor={p?.secondaryTextColor??'rgba(255,255,255,.3)'}/></View>{hint?<Text style={s.note}>{hint}</Text>:null}</View>}
function Field({label,value,onChange,keyboard='default',suffix}:{label:string;value:string;onChange:(s:string)=>void;keyboard?:any;suffix?:string}){const p=theme();const id=label.replace(/\s/g,'-');return <View style={s.field}><EditableText id={`form:${id}:label`} kind="label" systemName={label} style={[s.fieldLabel,{color:p?.secondaryTextColor??'rgba(255,255,255,.56)'}]}/><View style={s.inputWrap}><TextInput accessibilityLabel={label} style={[s.input,{color:p?.primaryTextColor??'#fff'}]} value={value} onChangeText={onChange} keyboardType={keyboard} placeholderTextColor={p?.secondaryTextColor??'rgba(255,255,255,.3)'}/><EditableText id={`form:${id}:suffix`} kind="label" systemName={suffix??''} style={[s.suffix,{color:p?.secondaryTextColor??'rgba(255,255,255,.4)'}]}/></View></View>}
