function Metric({label,value,positive,width}:{label:string;value:string;positive?:boolean;width?:ViewStyle['width']}){const p=theme();return <Card style={[s.metric,width?{width}:undefined]}><Text style={[s.muted,{color:p?.secondaryTextColor??'rgba(255,255,255,.55)'}]}>{label}</Text><Text style={[s.metricVal,{color:p?.primaryTextColor??'#fff'},positive!==undefined&&{color:positive?(p?.positiveColor??'#30d158'):(p?.negativeColor??'#ff6b61')}]}>{value}</Text></Card>}
function Mini({label,value,width,valueColor,scope}:{label:string;value:string;width?:ViewStyle['width'];valueColor?:string;scope?:string}){const p=theme();const id=`${scope?scope+':':''}${label.replace(/\s/g,'-')}`;const raw=parseDisplayNumber(value);const {editor,node}=useEditorNode(`metric:${id}:card`,'card',label);const palette={positive:p?.positiveColor??'#E54A45',negative:p?.negativeColor??'#12A875',neutral:p?.secondaryTextColor??'#8E9BAE'};const backgroundColor=resolveColor(node.backgroundColorMode??'theme',node.backgroundColor,'rgba(255,255,255,.035)',raw,palette);const borderColor=resolveColor(node.borderColorMode??'theme',node.borderColor,'rgba(255,255,255,.06)',raw,palette);return <TouchableOpacity activeOpacity={1} onLongPress={()=>editor?.open(node)} style={[width?{width,minWidth:0,flexGrow:0,flexBasis:'auto'}:undefined]}><EffectSurface effects={node.effects} radius={Math.min(8,p?.cardRadius??6)} style={[s.mini,{borderRadius:Math.min(8,p?.cardRadius??6),backgroundColor,borderColor},effectsStyle(node.effects,borderColor)]}><EditableText id={`metric:${id}:label`} kind="label" systemName={label} pnl={raw} style={[s.miniLabel,{color:p?.secondaryTextColor??'rgba(255,255,255,.48)'}]}/><EditableText id={`metric:${id}:value`} kind="value" systemName={value} pnl={raw} style={[s.miniValue,{color:valueColor??p?.primaryTextColor??'#fff'}]}>{value}</EditableText></EffectSurface></TouchableOpacity>}
