function fmtDate(d:Date){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function parseDate(v:string){const m=v.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return new Date();const d=new Date(Number(m[1]),Number(m[2])-1,Number(m[3]));return Number.isNaN(d.getTime())?new Date():d}
function parseTime(v:string){const [h,m]=v.split(':').map(Number);const d=new Date();d.setHours(Number.isFinite(h)?h:13,Number.isFinite(m)?m:35,0,0);return d}
